          "agendaSlot": "09:17–09:47",
          "bio": "AIDSO 爱搜 AI 合伙人。自述公司已深耕线上推广十余年、完整经历四个搜索时期，早年以应用商店优化（ASO）起家并服务数千家 APP 产品，近两三年专注以抖音为代表的超级 APP 站内搜索（DSO）及 GEO 业务，曾出席首届中国 GEO 大会。",
