              "text": "推翻旧分工后，讲者给出个人与团队的AI原生解法。个人心法是“让模型找到全球最好思路与最高要求，加上业务理解照着干”，人仅守建信任、谈利益、担责任、做承诺四条沟通红线，并用“写Skill的Skill”喂入好文章与大会录音冲击5级黑灯工厂。团队落地“调研→实操→自动化”三板斧与代码/录音对模型透明，改按“一人一事一上下文”分工并全员出Demo，岗位收敛为原型、建造、筛选、增长、维护五类。",
