              "text": "他由此提出内容核心逻辑：不要自夸产品多强，而是帮用户出攻略并让自己恰好成为攻略里的答案，既帮自己获客也帮「获客的客户再获客」。实操应坚持「一个痛点、一个场景、一个产品」单点突破，例如模拟久坐不想运动节食的减肥心理，或深圳牙痛就近找牙医的真实问法，直接对接 AI 匹配机制。",
