          "bio": "第二届中国 GEO 大会闭幕压轴环节（11 月 22 日 17:50–18:55，全程约 65 分钟）。姚金刚与乔向阳（乔木）围绕现场参会会员与线上直播间观众交替提出的 13 轮一线实战追问逐一拆解并致闭幕辞。本单元依据现场参会者飞书录音公开会场段完整还原，填补此前官方音频与开源全本的尾场空缺。",
          "title": "闭幕大答疑（13 轮）：归因算账、负面反向证据、豆包商品页、跨平台 Skill 逆向、出海多语种与预训练辟谣",
