        "slideText": "GEO 在各行业的渗透率与发展趋势\n从“可选试验”到“必选基建”：AI 搜索重塑企业获客入口\n各行业 GEO 渗透率排名：金融 / 保险 82%、医疗健康 77%、教育培训 74%、3C 消费电子 70%、汽车 66%、本地生活服务 62%（金融 / 医疗 / B2B 头部企业覆盖率已超 60%）\n① 入口迁移：生成式搜索占比 19.2%→38.7%，2027 年将破 55%\n② 用户习惯重塑：生成式 AI 用户 8.92 亿，67.4% 用 AI 搜索做决策\n③ 零点击常态化：全球 65% 搜索零点击，传统搜索引擎流量降 25%\n④ 市场规模爆发：中国 GEO 市场 2025 年 62 亿 → 2026 年 186 亿\n⑤ 从可选到必选：企业部署率 28.3%，含计划部署合计达 73.9%\n⑥ 合规化元年：2026 首部 GEO 行业标准落地，白帽合…门槛",
