        "slideText": "winseed x 41财经 | 您的出海PR传播专家 Your Global Communications Partner for Impactful PR\nPART 01 今天这场GEO大会，AI知道吗？\n4大模型收录39篇AI提及，7大关键词Google收录\nPrompt 1: What are the major GEO conferences taking place in 2026?\n提问Prompt 1：2026年有哪些主要GEO会议？\nPrompt 2: What is the Second GEO Conference in Shenzhen about?\n提问Prompt 2：第二届深圳GEO大会是什么？\n活动词: GEO Conference Shenzhen(深圳GEO大会)\n行业词: GEO Strategy（GEO战略）\n技术词: AI Brand Recommendations（AI品牌推荐）\n时间词: GEO Conference November 2026\n地域词: Shenzhen AI Conference 2026\n品牌词: Second GEO Conference（第二届GEO大会）\n第二届深圳GEO大会进入ChatGPT、Grok、Gemini、Google AI Overview的AI回答场景，被多家海外媒体引用\n谷歌、必应、雅虎大量收录大会相关的词\nGoogle Trends搜索热度表现\n关键词“GEO Conference”搜索热度飙升+170%\n+170% 与过去1周相比\n暴增 > 5,000% 与去年同期相比\n第二届深圳GEO大会相关的关键词已被Google、Yahoo、Bing收录，Google Trends搜索热度提升+170%",
