        "caption": "岚叔介绍个人履历（AI Agent 研发者、科技博主、企业 AI Native 转型与 FDE 顾问、GitHub 万星开发者）与个人主页 lanshuagent.com",
        "slideText": "— 开场 关于讲者 | 个人网站 lanshuagent.com | X x.com/lanshu\n我是岚叔：做 Agent 开发，也帮企业把 AI 落地\nAI Agent 研发者 · 科技博主 | 企业 AI Native 转型与 FDE 顾问\n企业 IT 全栈设计 · 曾维护百万容器集群 · 模型私有化 · 持续深度实测主流大模型与 Agent 架构 · GitHub 万星开发者\n01 一线 AI 实战派：Agent 架构研发 · 主流模型拆解\n02 赋能企业 AI 转型：AI Native 实战培训 · FDE 驻场交付\n03 打造全栈 AI 产品：协作 Agent · 视频平台 · 私有化部署\n04 大型集群与开源：企业级 IT 架构迁移 · 开源项目维护\n今天视角：既写 Agent、做模型与视频底层落地，也做业务网站——从 Agent 内部往外看，品牌怎样被选中。 02",
