        "caption": "岚叔梳理「四类 Agent：从写代码，到接管个人委托」（Coding · Claw · Work · Personal），并给出 OpenClaw、Claude Cowork、Muse 等代表产品",
        "slideText": "— 开场 Agent 形态演进\n四类 Agent：从写代码，到接管个人委托\n01 Coding 代码仓库交付：读项目、改代码、跑测试，凭执行反馈闭环。（Claude Code · Cursor）\n02 Claw 常驻记忆与技能：跨会话留住上下文，把经验沉淀为复用技能。（OpenClaw · Hermes）\n03 Work 岗位成果交付：连接本地文件与企业应用，直接交付工作成果。（Claude Cowork · M365 Copilot）\n04 Personal 个人长期委托：带着目标、偏好与授权，跨应用持续替人办事。（Muse · Grok Bot · OpenAI Dots）\n启示 Agent 从单次问答走向持续委托——品牌要进入它下次仍会复用的资料、技能与工具。 06",
