        "caption": "路浩展示 1,880 万条回答多语言对比：「AI 推的品牌，跟着当地人的问法和语言变」，拆解美、英、德三国 SUV 前三推荐差异",
        "slideText": "Dageno.ai\n— 在哪做 · 换个国家，榜单就变\nAI 推的品牌，跟着当地人的问法和语言变\n每组问 100 次，两组 AI 推的前 10 个品牌里有几个一样\n美国，同样的问题分两组问 7.2 个\n美国和英国，问同一句英文 6.9 个\n美国和英国，各用当地说法问 5.3 个\n美国和德国，各用当地说法问 4.0 个\n397 个品类，每个品类比 30 轮，每行约 1.2 万次对比；数据来自美、英、德约 1,880 万条回答\n例子：问 SUV，各国 AI 推得最多的 3 个品牌\n美国 Hyundai 27% Toyota 26% Kia 23%\n德国 Volkswagen 34% BMW 31% Mercedes 28%\n英国 BMW 32% Kia 29% Hyundai 24%\n所以：做海外，要用当地人的说法和语言去测、去做。\n数据：Dageno GeoLab · 2026 年 10–11 月",
        "objectKey": "ai7_prod_102265887_826326"
